+	tasks := make(chan bruteTask, workers*2)
+	var wg sync.WaitGroup
+	var found atomic.Bool
+	var resultMu sync.Mutex
+	result := SearchResult{}
+
+	for worker := 0; worker < workers; worker++ {
+		wg.Add(1)
+		go func() {
+			defer wg.Done()
+			for task := range tasks {
+				if found.Load() {
+					continue
+				}
+				password, ok := runBruteTask(target, charset, index, task, &found)
+				if ok && found.CompareAndSwap(false, true) {
+					resultMu.Lock()
+					result = SearchResult{Found: true, Password: password}
+					resultMu.Unlock()
+				}
+			}
+		}()
+	}
+
+	startBytes := []byte(startingPassword)
+	for length := minLen; length <= maxLen; length++ {
+		if found.Load() {
+			break
+		}
+		if len(startBytes) > 0 && length < len(startBytes) {
+			continue
+		}
+
+		var fullStart []byte
+		if len(startBytes) > 0 && length == len(startBytes) {
+			fullStart = startBytes
+		}
+
+		prefixLen := choosePrefixLen(len(charset), length, workers)
+		emitBruteTasks(tasks, charset, length, prefixLen, fullStart, &found)
+	}
+
+	close(tasks)
+	wg.Wait()
+
+	resultMu.Lock()
+	defer resultMu.Unlock()
+	return result
+}
+
+func runBruteTask(target *Target, charset []byte, index [256]int, task bruteTask, found *atomic.Bool) (string, bool) {
+	suffixLen := task.totalLength - len(task.prefix)
+	candidate := make([]byte, task.totalLength)
+	copy(candidate, task.prefix)
+	if suffixLen == 0 {
+		if target.CheckPassword(candidate) {
+			return string(candidate), true
+		}
+		return "", false
+	}
+
+	digits := make([]int, suffixLen)
+	for i := 0; i < suffixLen; i++ {
+		digits[i] = index[task.startSuffix[i]]
+		candidate[len(task.prefix)+i] = charset[digits[i]]
+	}
+
+	for {
+		if found.Load() {
+			return "", false
+		}
+		if target.CheckPassword(candidate) {
+			return string(candidate), true
+		}
+		if !incrementDigits(digits, charset) {
+			return "", false
+		}
+		for i, digit := range digits {
+			candidate[len(task.prefix)+i] = charset[digit]
+		}
+	}
+}
+
+func incrementDigits(digits []int, charset []byte) bool {
+	last := len(digits) - 1
+	for position := last; position >= 0; position-- {
+		digits[position]++
+		if digits[position] < len(charset) {
+			for reset := position + 1; reset <= last; reset++ {
+				digits[reset] = 0
+			}
+			return true
+		}
+	}
+	return false
+}
+
+func choosePrefixLen(base int, length int, workers int) int {
+	if length <= 0 {
+		return 0
+	}
+	prefixLen := 1
+	count := base
+	for prefixLen < length && count < workers {
+		if count > workers {
+			break
+		}
+		count *= base
+		prefixLen++
+	}
+	return prefixLen
+}
+
+func emitBruteTasks(tasks chan<- bruteTask, charset []byte, length int, prefixLen int, fullStart []byte, found *atomic.Bool) {
+	if prefixLen <= 0 {
+		return
+	}
+
+	prefix := make([]byte, prefixLen)
+	var walk func(int)
+	walk = func(position int) {
+		if found.Load() {
+			return
+		}
+		if position == prefixLen {
+			startSuffix := bytes.Repeat([]byte{charset[0]}, length-prefixLen)
+			if len(fullStart) > 0 {
+				cmp := bytes.Compare(prefix, fullStart[:prefixLen])
+				if cmp < 0 {
+					return
+				}
+				if cmp == 0 {
+					startSuffix = append(startSuffix[:0], fullStart[prefixLen:]...)
+				}
+			}
+			taskPrefix := append([]byte(nil), prefix...)
+			taskStart := append([]byte(nil), startSuffix...)
+			tasks <- bruteTask{
+				prefix:      taskPrefix,
+				startSuffix: taskStart,
+				totalLength: length,
+			}
+			return
+		}
+		for _, ch := range charset {
+			prefix[position] = ch
+			walk(position + 1)
+			if found.Load() {
+				return
+			}
+		}
+	}
+	walk(0)
+}
+
+func buildIndexLookup(charset []byte) [256]int {
+	var index [256]int
+	for i := range index {
+		index[i] = -1
+	}
+	for i, ch := range charset {
+		index[ch] = i
+	}
+	return index
+}
+
+func emitEmptyCharsetPanics(workers int) {
+	for worker := 1; worker <= workers; worker++ {
+		fmt.Fprintf(os.Stderr, "thread 'worker-%d' (%d) panicked at src/password_gen.rs:60:46:\ncharset non empty\n", worker, 1000+worker)
+		if worker == 1 {
+			fmt.Fprintln(os.Stderr, "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace")
+		}
+		fmt.Fprintln(os.Stderr)
+	}
+}
