package main

import (
	"errors"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"time"
)

const helpText = `Find the password of protected ZIP files

Usage: executable [OPTIONS] --inputFile <inputFile>

Options:
  -i, --inputFile <inputFile>                    path to zip input file
  -w, --workers <workers>                        number of workers
  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file
  -c, --charset <charset>                        charset to use to generate password [default: lud]
      --charsetFile <charsetFile>                path to a charset file
      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]
      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]
      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]
  -s, --startingPassword <startingPassword>      password to start from
  -h, --help                                     Print help
  -V, --version                                  Print version
`

const versionText = "zip-password-finder 0.10.3"

type Config struct {
	InputFile          string
	Workers            int
	PasswordDictionary string
	Charset            string
	CharsetFile        string
	MinPasswordLen     int
	MaxPasswordLen     int
	FileNumber         int
	StartingPassword   string
}

type cliError struct {
	ExitCode int
	Output   string
}

func (e *cliError) Error() string {
	return e.Output
}

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	cfg, err := parseArgs(args)
	if err != nil {
		var cliErr *cliError
		if errors.As(err, &cliErr) {
			_, _ = fmt.Fprint(os.Stderr, cliErr.Output)
			return cliErr.ExitCode
		}
		_, _ = fmt.Fprintf(os.Stderr, "%v\n", err)
		return 1
	}

	if err := validateRegularFile(cfg.InputFile, "inputFile"); err != nil {
		return printCustomError(err)
	}
	if cfg.PasswordDictionary != "" {
		if err := validateRegularFile(cfg.PasswordDictionary, "passwordDictionary"); err != nil {
			return printCustomError(err)
		}
	}
	if cfg.CharsetFile != "" {
		if err := validateRegularFile(cfg.CharsetFile, "charsetFile"); err != nil {
			return printCustomError(err)
		}
	}
	if cfg.Workers <= 0 {
		return printCustomError(errors.New("CLI argument error - \"'workers' must be positive\""))
	}
	if cfg.MinPasswordLen <= 0 {
		return printCustomError(errors.New("CLI argument error - \"'minPasswordLen' must be positive\""))
	}
	if cfg.MaxPasswordLen <= 0 {
		return printCustomError(errors.New("CLI argument error - \"'maxPasswordLen' must be positive\""))
	}
	if cfg.MaxPasswordLen < cfg.MinPasswordLen {
		return printCustomError(errors.New("CLI argument error - \"'maxPasswordLen' must be equal or greater than 'minPasswordLen'\""))
	}
	if cfg.PasswordDictionary != "" && cfg.StartingPassword != "" {
		return printCustomError(errors.New("CLI argument error - \"'startingPassword' cannot be used with a dictionary file\""))
	}

	var charset []byte
	if cfg.PasswordDictionary == "" {
		var buildErr error
		charset, buildErr = buildCharset(cfg.Charset, cfg.CharsetFile)
		if buildErr != nil {
			return printCustomError(buildErr)
		}
		if cfg.StartingPassword != "" {
			if !allInCharset([]byte(cfg.StartingPassword), charset) {
				return printCustomError(errors.New("CLI argument error - \"'startingPassword' uses characters out of the generation charset\""))
			}
			if len(cfg.StartingPassword) < cfg.MinPasswordLen || len(cfg.StartingPassword) > cfg.MaxPasswordLen {
				return printCustomError(errors.New("CLI argument error - \"'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration\""))
			}
		}
	}

	target, err := openTarget(cfg.InputFile, cfg.FileNumber)
	if err != nil {
		return printCustomError(err)
	}

	start := time.Now()
	var result SearchResult
	if cfg.PasswordDictionary != "" {
		result, err = dictionarySearch(target, cfg.PasswordDictionary, cfg.Workers)
	} else {
		result = bruteForceSearch(target, charset, cfg.MinPasswordLen, cfg.MaxPasswordLen, cfg.StartingPassword, cfg.Workers)
	}
	if err != nil {
		return printCustomError(err)
	}

	fmt.Printf("Time elapsed: %s\n", formatDuration(time.Since(start)))
	if result.Found {
		fmt.Printf("Password found:%s\n", result.Password)
	} else {
		fmt.Println("Password not found")
	}
	return 0
}

func parseArgs(args []string) (Config, error) {
	cfg := Config{
		Workers:        defaultWorkers(),
		Charset:        "lud",
		MinPasswordLen: 1,
		MaxPasswordLen: 10,
		FileNumber:     0,
	}

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "-h" || arg == "--help":
			fmt.Print(helpText)
			return cfg, &cliError{ExitCode: 0}
		case arg == "-V" || arg == "--version":
			fmt.Println(versionText)
			return cfg, &cliError{ExitCode: 0}
		case arg == "-i" || arg == "--inputFile":
			val, consumed, err := takeValue(args, i, "--inputFile", "<inputFile>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			if val != "" {
				cfg.InputFile = val
			}
		case strings.HasPrefix(arg, "--inputFile="):
			cfg.InputFile = strings.TrimPrefix(arg, "--inputFile=")
		case arg == "-w" || arg == "--workers":
			val, consumed, err := takeValue(args, i, "--workers", "<workers>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			if val != "" {
				num, parseErr := parseNonNegativeInt(val, "--workers", "<workers>")
				if parseErr != nil {
					return cfg, parseErr
				}
				cfg.Workers = num
			}
		case strings.HasPrefix(arg, "--workers="):
			num, parseErr := parseNonNegativeInt(strings.TrimPrefix(arg, "--workers="), "--workers", "<workers>")
			if parseErr != nil {
				return cfg, parseErr
			}
			cfg.Workers = num
		case arg == "-p" || arg == "--passwordDictionary":
			val, consumed, err := takeValue(args, i, "--passwordDictionary", "<passwordDictionary>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			if val != "" {
				cfg.PasswordDictionary = val
			}
		case strings.HasPrefix(arg, "--passwordDictionary="):
			cfg.PasswordDictionary = strings.TrimPrefix(arg, "--passwordDictionary=")
		case arg == "-c" || arg == "--charset":
			val, consumed, err := takeValue(args, i, "--charset", "<charset>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			cfg.Charset = val
		case strings.HasPrefix(arg, "--charset="):
			cfg.Charset = strings.TrimPrefix(arg, "--charset=")
		case arg == "--charsetFile":
			val, consumed, err := takeValue(args, i, "--charsetFile", "<charsetFile>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			cfg.CharsetFile = val
		case strings.HasPrefix(arg, "--charsetFile="):
			cfg.CharsetFile = strings.TrimPrefix(arg, "--charsetFile=")
		case arg == "--minPasswordLen":
			val, consumed, err := takeValue(args, i, "--minPasswordLen", "<minPasswordLen>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			if val != "" {
				num, parseErr := parseNonNegativeInt(val, "--minPasswordLen", "<minPasswordLen>")
				if parseErr != nil {
					return cfg, parseErr
				}
				cfg.MinPasswordLen = num
			}
		case strings.HasPrefix(arg, "--minPasswordLen="):
			num, parseErr := parseNonNegativeInt(strings.TrimPrefix(arg, "--minPasswordLen="), "--minPasswordLen", "<minPasswordLen>")
			if parseErr != nil {
				return cfg, parseErr
			}
			cfg.MinPasswordLen = num
		case arg == "--maxPasswordLen":
			val, consumed, err := takeValue(args, i, "--maxPasswordLen", "<maxPasswordLen>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			if val != "" {
				num, parseErr := parseNonNegativeInt(val, "--maxPasswordLen", "<maxPasswordLen>")
				if parseErr != nil {
					return cfg, parseErr
				}
				cfg.MaxPasswordLen = num
			}
		case strings.HasPrefix(arg, "--maxPasswordLen="):
			num, parseErr := parseNonNegativeInt(strings.TrimPrefix(arg, "--maxPasswordLen="), "--maxPasswordLen", "<maxPasswordLen>")
			if parseErr != nil {
				return cfg, parseErr
			}
			cfg.MaxPasswordLen = num
		case arg == "--fileNumber":
			val, consumed, err := takeValue(args, i, "--fileNumber", "<fileNumber>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			if val != "" {
				num, parseErr := parseNonNegativeInt(val, "--fileNumber", "<fileNumber>")
				if parseErr != nil {
					return cfg, parseErr
				}
				cfg.FileNumber = num
			}
		case strings.HasPrefix(arg, "--fileNumber="):
			num, parseErr := parseNonNegativeInt(strings.TrimPrefix(arg, "--fileNumber="), "--fileNumber", "<fileNumber>")
			if parseErr != nil {
				return cfg, parseErr
			}
			cfg.FileNumber = num
		case arg == "-s" || arg == "--startingPassword":
			val, consumed, err := takeValue(args, i, "--startingPassword", "<startingPassword>")
			if err != nil {
				return cfg, err
			}
			if consumed {
				i++
			}
			cfg.StartingPassword = val
		case strings.HasPrefix(arg, "--startingPassword="):
			cfg.StartingPassword = strings.TrimPrefix(arg, "--startingPassword=")
		case strings.HasPrefix(arg, "-"):
			return cfg, unexpectedArgumentError(arg)
		default:
			return cfg, unexpectedArgumentError(arg)
		}
	}

	if cfg.InputFile == "" {
		return cfg, &cliError{
			ExitCode: 2,
			Output: "error: the following required arguments were not provided:\n" +
				"  --inputFile <inputFile>\n\n" +
				"Usage: executable --inputFile <inputFile>\n\n" +
				"For more information, try '--help'.\n",
		}
	}

	return cfg, nil
}

func takeValue(args []string, index int, longOpt string, placeholder string) (string, bool, error) {
	if index+1 >= len(args) {
		return "", false, missingValueError(longOpt, placeholder)
	}
	next := args[index+1]
	if strings.HasPrefix(next, "-") {
		if isNegativeNumberToken(next) {
			return "", false, nil
		}
		return "", false, missingValueError(longOpt, placeholder)
	}
	return next, true, nil
}

func parseNonNegativeInt(value string, longOpt string, placeholder string) (int, error) {
	if strings.HasPrefix(value, "-") {
		return 0, invalidValueError(value, longOpt, placeholder)
	}
	num, err := strconv.Atoi(value)
	if err != nil {
		return 0, invalidValueError(value, longOpt, placeholder)
	}
	return num, nil
}

func invalidValueError(value string, longOpt string, placeholder string) error {
	return &cliError{
		ExitCode: 2,
		Output: fmt.Sprintf("error: invalid value '%s' for '%s %s': invalid digit found in string\n\nFor more information, try '--help'.\n", value, longOpt, placeholder),
	}
}

func missingValueError(longOpt string, placeholder string) error {
	return &cliError{
		ExitCode: 2,
		Output: fmt.Sprintf("error: a value is required for '%s %s' but none was supplied\n\nFor more information, try '--help'.\n", longOpt, placeholder),
	}
}

func unexpectedArgumentError(arg string) error {
	return &cliError{
		ExitCode: 2,
		Output: fmt.Sprintf("error: unexpected argument '%s' found\n\nUsage: executable [OPTIONS] --inputFile <inputFile>\n\nFor more information, try '--help'.\n", arg),
	}
}

func validateRegularFile(path string, field string) error {
	info, err := os.Stat(path)
	if err != nil || !info.Mode().IsRegular() {
		return fmt.Errorf("CLI argument error - \"'%s' does not exist\"", field)
	}
	return nil
}

func buildCharset(spec string, charsetFile string) ([]byte, error) {
	var chars []byte
	if charsetFile != "" {
		data, err := os.ReadFile(charsetFile)
		if err != nil {
			return nil, fmt.Errorf("CLI argument error - \"'charsetFile' does not exist\"")
		}
		chars = append(chars, data...)
	} else {
		for i := 0; i < len(spec); i++ {
			switch spec[i] {
			case 'l':
				chars = append(chars, []byte("abcdefghijklmnopqrstuvwxyz")...)
			case 'u':
				chars = append(chars, []byte("ABCDEFGHIJKLMNOPQRSTUVWXYZ")...)
			case 'd':
				chars = append(chars, []byte("0123456789")...)
			case 'h':
				chars = append(chars, []byte("0123456789abcdef")...)
			case 'H':
				chars = append(chars, []byte("0123456789ABCDEF")...)
			case 's':
				chars = append(chars, []byte(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")...)
			default:
				return nil, fmt.Errorf("CLI argument error - \"Unknown charset option '%c'\"", spec[i])
			}
		}
	}

	sort.Slice(chars, func(i, j int) bool {
		return chars[i] < chars[j]
	})
	return dedupeBytes(chars), nil
}

func dedupeBytes(chars []byte) []byte {
	if len(chars) == 0 {
		return chars
	}
	out := make([]byte, 0, len(chars))
	last := chars[0]
	out = append(out, last)
	for _, ch := range chars[1:] {
		if ch != last {
			out = append(out, ch)
			last = ch
		}
	}
	return out
}

func allInCharset(password []byte, charset []byte) bool {
	if len(password) == 0 {
		return true
	}
	var present [256]bool
	for _, ch := range charset {
		present[ch] = true
	}
	for _, ch := range password {
		if !present[ch] {
			return false
		}
	}
	return true
}

func printCustomError(err error) int {
	_, _ = fmt.Fprintln(os.Stderr, err.Error())
	return 1
}

func defaultWorkers() int {
	count := physicalCoreCount()
	if count > 0 {
		return count
	}
	return 1
}

func physicalCoreCount() int {
	data, err := os.ReadFile("/proc/cpuinfo")
	if err != nil {
		return 1
	}

	type empty struct{}
	cores := make(map[string]empty)
	block := make(map[string]string)
	lines := strings.Split(string(data), "\n")
	flush := func() {
		physicalID, okPhysical := block["physical id"]
		coreID, okCore := block["core id"]
		if okPhysical && okCore {
			cores[physicalID+"/"+coreID] = empty{}
		}
		block = make(map[string]string)
	}

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			flush()
			continue
		}
		parts := strings.SplitN(line, ":", 2)
		if len(parts) == 2 {
			block[strings.TrimSpace(parts[0])] = strings.TrimSpace(parts[1])
		}
	}
	if len(block) > 0 {
		flush()
	}
	if len(cores) > 0 {
		return len(cores)
	}
	return 1
}

func isNegativeNumberToken(value string) bool {
	if len(value) < 2 || value[0] != '-' {
		return false
	}
	for i := 1; i < len(value); i++ {
		if value[i] < '0' || value[i] > '9' {
			return false
		}
	}
	return true
}

func formatDuration(d time.Duration) string {
	remaining := d.Nanoseconds()
	if remaining <= 0 {
		return "0s"
	}

	type unit struct {
		label string
		size  int64
	}
	units := []unit{
		{label: "h", size: int64(time.Hour)},
		{label: "m", size: int64(time.Minute)},
		{label: "s", size: int64(time.Second)},
		{label: "ms", size: int64(time.Millisecond)},
		{label: "us", size: int64(time.Microsecond)},
		{label: "ns", size: 1},
	}

	parts := make([]string, 0, len(units))
	for _, unit := range units {
		if remaining >= unit.size {
			count := remaining / unit.size
			remaining %= unit.size
			parts = append(parts, fmt.Sprintf("%d%s", count, unit.label))
		}
	}
	if len(parts) == 0 {
		return "0s"
	}
	return strings.Join(parts, " ")
}

