package main

import (
	"archive/zip"
	"bytes"
	"compress/flate"
	"crypto/aes"
	"crypto/hmac"
	"crypto/sha1"
	"encoding/binary"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"strings"
)

type Target struct {
	Name             string
	Flags            uint16
	Method           uint16
	ModifiedTime     uint16
	CRC32            uint32
	UncompressedSize uint64
	Raw              []byte
	AES              *AESInfo
}

type AESInfo struct {
	Version      uint16
	Strength     byte
	ActualMethod uint16
}

func openTarget(path string, fileNumber int) (*Target, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("Invalid zip file error - invalid Zip archive: Could not find EOCD")
	}
	defer file.Close()

	info, err := file.Stat()
	if err != nil {
		return nil, fmt.Errorf("Invalid zip file error - invalid Zip archive: Could not find EOCD")
	}

	reader, err := zip.NewReader(file, info.Size())
	if err != nil {
		return nil, fmt.Errorf("Invalid zip file error - invalid Zip archive: Could not find EOCD")
	}
	if fileNumber < 0 || fileNumber >= len(reader.File) {
		return nil, fmt.Errorf("File number not found within archive error - '%d'", fileNumber)
	}

	entry := reader.File[fileNumber]
	if entry.Flags&0x1 == 0 {
		return nil, fmt.Errorf("Invalid zip file error - the selected file in the archive is not encrypted (file_number:%d file_name:%s)", fileNumber, entry.Name)
	}

	offset, err := entry.DataOffset()
	if err != nil {
		return nil, fmt.Errorf("Invalid zip file error - invalid Zip archive: Could not find EOCD")
	}

	raw := make([]byte, entry.CompressedSize64)
	if _, err := file.ReadAt(raw, offset); err != nil {
		return nil, fmt.Errorf("Invalid zip file error - invalid Zip archive: Could not find EOCD")
	}

	target := &Target{
		Name:             entry.Name,
		Flags:            entry.Flags,
		Method:           entry.Method,
		ModifiedTime:     entry.ModifiedTime,
		CRC32:            entry.CRC32,
		UncompressedSize: entry.UncompressedSize64,
		Raw:              raw,
	}
	if entry.Method == 99 {
		aesInfo, err := parseAESInfo(entry.Extra)
		if err != nil {
			return nil, fmt.Errorf("Invalid zip file error - invalid Zip archive: %v", err)
		}
		target.AES = aesInfo
	}
	return target, nil
}

func parseAESInfo(extra []byte) (*AESInfo, error) {
	for len(extra) >= 4 {
		headerID := binary.LittleEndian.Uint16(extra[0:2])
		size := int(binary.LittleEndian.Uint16(extra[2:4]))
		extra = extra[4:]
		if size > len(extra) {
			break
		}
		body := extra[:size]
		extra = extra[size:]
		if headerID == 0x9901 && len(body) >= 7 {
			return &AESInfo{
				Version:      binary.LittleEndian.Uint16(body[0:2]),
				Strength:     body[4],
				ActualMethod: binary.LittleEndian.Uint16(body[5:7]),
			}, nil
		}
	}
	return nil, fmt.Errorf("missing AES metadata")
}

func (t *Target) CheckPassword(password []byte) bool {
	if t.AES != nil {
		return t.checkAESPassword(password)
	}
	return t.checkZipCryptoPassword(password)
}

func (t *Target) checkZipCryptoPassword(password []byte) bool {
	if len(t.Raw) < 12 {
		return false
	}

	keys := newZipCryptoKeys(password)
	header := make([]byte, 12)
	for i := 0; i < 12; i++ {
		header[i] = keys.decrypt(t.Raw[i])
	}

	if header[11] != t.zipCryptoCheckByte() {
		return false
	}

	plaintext := make([]byte, len(t.Raw)-12)
	for i := 12; i < len(t.Raw); i++ {
		plaintext[i-12] = keys.decrypt(t.Raw[i])
	}

	data, err := decompressData(plaintext, t.Method)
	if err != nil {
		return false
	}
	if crc32.ChecksumIEEE(data) != t.CRC32 {
		return false
	}
	return uint64(len(data)) == t.UncompressedSize
}

func (t *Target) zipCryptoCheckByte() byte {
	if t.Flags&0x8 != 0 {
		return byte(t.ModifiedTime >> 8)
	}
	return byte(t.CRC32 >> 24)
}

func (t *Target) checkAESPassword(password []byte) bool {
	if len(t.Raw) < 12 {
		return false
	}

	saltLen, keyLen := aesParams(t.AES.Strength)
	if len(t.Raw) < saltLen+2+10 {
		return false
	}

	salt := t.Raw[:saltLen]
	passwordVerifier := t.Raw[saltLen : saltLen+2]
	authCode := t.Raw[len(t.Raw)-10:]
	ciphertext := t.Raw[saltLen+2 : len(t.Raw)-10]

	derived := pbkdf2SHA1(password, salt, 1000, 2*keyLen+2)
	encKey := derived[:keyLen]
	authKey := derived[keyLen : 2*keyLen]
	expectedVerifier := derived[2*keyLen:]

	if !bytes.Equal(passwordVerifier, expectedVerifier) {
		return false
	}

	mac := hmac.New(sha1.New, authKey)
	_, _ = mac.Write(ciphertext)
	if !hmac.Equal(authCode, mac.Sum(nil)[:10]) {
		return false
	}

	plaintext, err := aesCTRDecrypt(encKey, ciphertext)
	if err != nil {
		return false
	}
	data, err := decompressData(plaintext, t.AES.ActualMethod)
	if err != nil {
		return false
	}
	if t.AES.Version == 1 && crc32.ChecksumIEEE(data) != t.CRC32 {
		return false
	}
	if t.UncompressedSize > 0 && uint64(len(data)) != t.UncompressedSize {
		return false
	}
	return true
}

func aesParams(strength byte) (saltLen int, keyLen int) {
	switch strength {
	case 1:
		return 8, 16
	case 2:
		return 12, 24
	case 3:
		return 16, 32
	default:
		return 8, 16
	}
}

func aesCTRDecrypt(key []byte, ciphertext []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}

	plaintext := make([]byte, len(ciphertext))
	counterBlock := make([]byte, 16)
	keystream := make([]byte, 16)
	counter := uint32(1)
	for offset := 0; offset < len(ciphertext); offset += len(keystream) {
		for i := range counterBlock {
			counterBlock[i] = 0
		}
		binary.LittleEndian.PutUint32(counterBlock[:4], counter)
		block.Encrypt(keystream, counterBlock)
		chunkLen := len(ciphertext) - offset
		if chunkLen > len(keystream) {
			chunkLen = len(keystream)
		}
		for i := 0; i < chunkLen; i++ {
			plaintext[offset+i] = ciphertext[offset+i] ^ keystream[i]
		}
		counter++
	}
	return plaintext, nil
}

func pbkdf2SHA1(password []byte, salt []byte, iterations int, keyLen int) []byte {
	const hLen = 20
	blockCount := (keyLen + hLen - 1) / hLen
	output := make([]byte, 0, blockCount*hLen)
	buffer := make([]byte, len(salt)+4)
	copy(buffer, salt)

	for block := 1; block <= blockCount; block++ {
		binary.BigEndian.PutUint32(buffer[len(salt):], uint32(block))

		mac := hmac.New(sha1.New, password)
		_, _ = mac.Write(buffer)
		u := mac.Sum(nil)

		t := make([]byte, len(u))
		copy(t, u)

		for i := 1; i < iterations; i++ {
			mac = hmac.New(sha1.New, password)
			_, _ = mac.Write(u)
			u = mac.Sum(nil)
			for j := range t {
				t[j] ^= u[j]
			}
		}
		output = append(output, t...)
	}
	return output[:keyLen]
}

func decompressData(data []byte, method uint16) ([]byte, error) {
	switch method {
	case zip.Store:
