func (z *zipCryptoKeys) magicByte() byte {
	temp := uint16(z.key2&0xffff) | 2
	return byte((uint32(temp) * uint32(temp^1) >> 8) & 0xff)
}

func crc32update(current uint32, value byte) uint32 {
	return crc32.IEEETable[(current^uint32(value))&0xff] ^ (current >> 8)
}

